	// nonzero even when a tool is not in logical contact. See the down and up
	// events for more details.
	pressure(proxy ZwpTabletToolV1, pressure u32)
	// Sent whenever the distance axis on a tool changes. The value of this event
	// is normalized to a value between 0 and 65535. Note that distance may be
	// nonzero even when a tool is not in logical contact. See the down and up
	// events for more details.
	distance(proxy ZwpTabletToolV1, distance u32)
	// Sent whenever one or both of the tilt axes on a tool change. Each tilt
	// value is in 0.01 of a degree, relative to the z-axis of the tablet. The
	// angle is positive when the top of a tool tilts along the positive x or y
	// axis.
	tilt(proxy ZwpTabletToolV1, tilt_x i32, tilt_y i32)
	// Sent whenever the z-rotation axis on the tool changes. The rotation value
	// is in 0.01 of a degree clockwise from the tool's logical neutral position.
	rotation(proxy ZwpTabletToolV1, degrees i32)
	// Sent whenever the slider position on the tool changes. The value is
	// normalized between -65535 and 65535, with 0 as the logical neutral
	// position of the slider. The slider is available on e.g. the Wacom Airbrush
	// tool.
	slider(proxy ZwpTabletToolV1, position i32)
	// Sent whenever the wheel on the tool emits an event. This event contains
	// two values for the same axis change. The degrees value is in 0.01 of a
	// degree in the same orientation as the wl_pointer.vertical_scroll axis. The
	// clicks value is in discrete logical clicks of the mouse wheel. This value
	// may be zero if the movement of the wheel was less than one logical click.
	// Clients should choose either value and avoid mixing degrees and clicks.
	// The compositor may accumulate values smaller than a logical click and
	// emulate click events when a certain threshold is met. Thus,
	// wl_tablet_tool.wheel events with non-zero clicks values may have different
	// degrees values.
	wheel(proxy ZwpTabletToolV1, degrees i32, clicks i32)
	// Sent whenever a button on the tool is pressed or released. If a button is
	// held down when the tool moves in or out of proximity, button events are
	// generated by the compositor. See wp_tablet_tool.proximity_in and
	// wp_tablet_tool.proximity_out for details.
	button(proxy ZwpTabletToolV1, serial u32, button u32, state u32)
	// Marks the end of a series of axis and/or button updates from the tablet.
	// The Wayland protocol requires axis updates to be sent sequentially,
	// however all events within a frame should be considered one hardware event.
	frame(proxy ZwpTabletToolV1, time u32)
}

