struct ZwpTabletToolV1Sink {
mut:
	proxy    ZwpTabletToolV1
	listener ZwpTabletToolV1Listener = NoopZwpTabletToolV1Listener{}
}

fn (mut s ZwpTabletToolV1Sink) on_event(msg &wayland.Message) !bool {
	match msg.opcode {
		0 {
			tool_type := msg.arg_u32(0)!
			s.listener.type_(s.proxy, tool_type)
		}
		1 {
			hardware_serial_hi := msg.arg_u32(0)!
			hardware_serial_lo := msg.arg_u32(1)!
			s.listener.hardware_serial(s.proxy, hardware_serial_hi, hardware_serial_lo)
		}
		2 {
			hardware_id_hi := msg.arg_u32(0)!
			hardware_id_lo := msg.arg_u32(1)!
			s.listener.hardware_id_wacom(s.proxy, hardware_id_hi, hardware_id_lo)
		}
		3 {
			capability := msg.arg_u32(0)!
			s.listener.capability(s.proxy, capability)
		}
		4 {
			s.listener.done(s.proxy)
		}
		5 {
			s.listener.removed(s.proxy)
		}
		6 {
			serial := msg.arg_u32(0)!
			tablet_id := msg.arg_id(1)!
			tablet := zwp_tablet_v1_proxy(s.proxy.conn, tablet_id)
			surface_id := msg.arg_id(2)!
			surface := wl.wl_surface_proxy(s.proxy.conn, surface_id)
			s.listener.proximity_in(s.proxy, serial, tablet, surface)
		}
		7 {
			s.listener.proximity_out(s.proxy)
		}
		8 {
			serial := msg.arg_u32(0)!
			s.listener.down(s.proxy, serial)
		}
		9 {
			s.listener.up(s.proxy)
		}
		10 {
			x := msg.arg_fixed(0)!.f64()
			y := msg.arg_fixed(1)!.f64()
			s.listener.motion(s.proxy, x, y)
		}
		11 {
			pressure := msg.arg_u32(0)!
			s.listener.pressure(s.proxy, pressure)
		}
		12 {
			distance := msg.arg_u32(0)!
			s.listener.distance(s.proxy, distance)
		}
		13 {
			tilt_x := msg.arg_int(0)!
			tilt_y := msg.arg_int(1)!
			s.listener.tilt(s.proxy, tilt_x, tilt_y)
		}
		14 {
			degrees := msg.arg_int(0)!
			s.listener.rotation(s.proxy, degrees)
		}
		15 {
			position := msg.arg_int(0)!
			s.listener.slider(s.proxy, position)
		}
		16 {
			degrees := msg.arg_int(0)!
			clicks := msg.arg_int(1)!
			s.listener.wheel(s.proxy, degrees, clicks)
		}
		17 {
			serial := msg.arg_u32(0)!
			button := msg.arg_u32(1)!
			state := msg.arg_u32(2)!
			s.listener.button(s.proxy, serial, button, state)
		}
		18 {
			time := msg.arg_u32(0)!
			s.listener.frame(s.proxy, time)
		}
		else {
			return false
		}
	}
	return true
}

// set_listener registers the handler that receives zwp_tablet_tool_v1 events.
pub fn (proxy &ZwpTabletToolV1) set_listener(listener ZwpTabletToolV1Listener) ! {
	proxy.conn.set_sink(proxy.id, ZwpTabletToolV1Sink{
		proxy:    *proxy
		listener: listener
	})!
}

// Sets the surface of the cursor used for this tool on the given tablet.
// This request only takes effect if the tool is in proximity of one of the
// requesting client's surfaces or the surface parameter is the current
// pointer surface. If there was a previous surface set with this request it
// is replaced. If surface is NULL, the cursor image is hidden. The
// parameters hotspot_x and hotspot_y define the position of the pointer
// surface relative to the pointer location. Its top-left corner is always at
// (x, y) - (hotspot_x, hotspot_y), where (x, y) are the coordinates of the
// pointer location, in surface-local coordinates. On surface.attach requests
// to the pointer surface, hotspot_x and hotspot_y are decremented by the x
// and y parameters passed to the request. Attach must be confirmed by
// wl_surface.commit as usual. The hotspot can also be updated by passing the
// currently set pointer surface to this request with new values for
// hotspot_x and hotspot_y. The current and pending input regions of the
// wl_surface are cleared, and wl_surface.set_input_region is ignored until
// the wl_surface is no longer used as the cursor. When the use as a cursor
// ends, the current and pending input regions become undefined, and the
// wl_surface is unmapped. This request gives the surface the role of a
// cursor. The role assigned by this request is the same as assigned by
// wl_pointer.set_cursor meaning the same surface can be used both as a
// wl_pointer cursor and a wp_tablet cursor. If the surface already has
// another role, it raises a protocol error. The surface may be used on
// multiple tablets and across multiple seats.
pub fn (proxy &ZwpTabletToolV1) set_cursor(serial u32, surface ?wl.WlSurface, hotspot_x i32, hotspot_y i32) ! {
	surface_id := if value := surface { value.id } else { u32(0) }
	proxy.conn.request(proxy.id, 0, [wayland.ArgValue(serial),
		wayland.ArgValue(wayland.ObjectRef{ id: surface_id }), wayland.ArgValue(hotspot_x),
		wayland.ArgValue(hotspot_y)])!
}

// This destroys the client's resource for this tool object.
pub fn (proxy &ZwpTabletToolV1) destroy() ! {
	proxy.conn.request(proxy.id, 1, []wayland.ArgValue{})!
	proxy.conn.destroy_object(proxy.id)
}

