// ZwpTabletV1 is a client side proxy for zwp_tablet_v1.
// The wp_tablet interface represents one graphics tablet device. The tablet
// interface itself does not generate events; all events are generated by
// wp_tablet_tool objects when in proximity above a tablet. A tablet has a
// number of static characteristics, e.g. device name and pid/vid. These
// capabilities are sent in an event sequence after the
// wp_tablet_seat.tablet_added event. This initial event sequence is
// terminated by a wp_tablet.done event.
pub struct ZwpTabletV1 {
	wayland.Object
}

// zwp_tablet_v1_proxy wraps an object id in a ZwpTabletV1 proxy.
pub fn zwp_tablet_v1_proxy(conn &wayland.Connection, id u32) ZwpTabletV1 {
	return ZwpTabletV1{
		Object: wayland.Object{
			id:    id
			conn:  conn
			iface: 'zwp_tablet_v1'
		}
	}
}

// ZwpTabletV1Listener receives the events of a zwp_tablet_v1 object.
pub interface ZwpTabletV1Listener {
	// This event is sent in the initial burst of events before the
	// wp_tablet.done event.
mut:
	name(proxy ZwpTabletV1, name string)
	// This event is sent in the initial burst of events before the
	// wp_tablet.done event.
	id(proxy ZwpTabletV1, vid u32, pid u32)
	// A system-specific device path that indicates which device is behind this
	// wp_tablet. This information may be used to gather additional information
	// about the device, e.g. through libwacom. A device may have more than one
	// device path. If so, multiple wp_tablet.path events are sent. A device may
	// be emulated and not have a device path, and in that case this event will
	// not be sent. The format of the path is unspecified, it may be a device
	// node, a sysfs path, or some other identifier. It is up to the client to
	// identify the string provided. This event is sent in the initial burst of
	// events before the wp_tablet.done event.
	path(proxy ZwpTabletV1, path string)
	// This event is sent immediately to signal the end of the initial burst of
	// descriptive events. A client may consider the static description of the
	// tablet to be complete and finalize initialization of the tablet.
	done(proxy ZwpTabletV1)
	// Sent when the tablet has been removed from the system. When a tablet is
	// removed, some tools may be removed. When this event is received, the
	// client must wp_tablet.destroy the object.
	removed(proxy ZwpTabletV1)
}

// NoopZwpTabletV1Listener ignores every zwp_tablet_v1 event. It is the default listener, so
// objects without a listener never fail on incoming events.
pub struct NoopZwpTabletV1Listener {}

