}

pub fn (mut listener NoopZwpTabletV1Listener) done(_proxy ZwpTabletV1) {
}

pub fn (mut listener NoopZwpTabletV1Listener) removed(_proxy ZwpTabletV1) {
}

struct ZwpTabletV1Sink {
mut:
	proxy    ZwpTabletV1
	listener ZwpTabletV1Listener = NoopZwpTabletV1Listener{}
}

fn (mut s ZwpTabletV1Sink) on_event(msg &wayland.Message) !bool {
	match msg.opcode {
		0 {
			name := msg.arg_string(0)!
			s.listener.name(s.proxy, name)
		}
		1 {
			vid := msg.arg_u32(0)!
			pid := msg.arg_u32(1)!
			s.listener.id(s.proxy, vid, pid)
		}
		2 {
			path := msg.arg_string(0)!
			s.listener.path(s.proxy, path)
		}
		3 {
			s.listener.done(s.proxy)
		}
		4 {
			s.listener.removed(s.proxy)
		}
		else {
			return false
		}
	}
	return true
}

