	proxy.conn.request(proxy.id, 0, []wayland.ArgValue{})!
	proxy.conn.destroy_object(proxy.id)
}

// bind_zwp_tablet_manager_v1 binds the zwp_tablet_manager_v1 global to a typed proxy.
pub fn bind_zwp_tablet_manager_v1(conn &wayland.Connection, global wayland.Global) !ZwpTabletManagerV1 {
	version := if global.version < zwp_tablet_manager_v1_desc.version {
		global.version
	} else {
		zwp_tablet_manager_v1_desc.version
	}
	object := conn.bind_global(global, 'zwp_tablet_manager_v1', version, &zwp_tablet_manager_v1_desc)!
	return ZwpTabletManagerV1{
		Object: object
	}
}
